#include <stdio.h>



int main(void) {
    int n, a[101], x;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    scanf("%d", &x);
    int pos = n;
    while (pos > 0 && a[pos - 1] > x) { a[pos] = a[pos - 1]; pos--; }
    a[pos] = x;
    for (int i = 0; i <= n; i++) printf("%d%c", a[i], i == n ? '\n' : ' ');
    return 0;
}
